package com.example.solarfarm.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthenticationFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var claims=jwt.parse(h.substring(7));var auth=new UsernamePasswordAuthenticationToken(claims.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+claims.get("role"))));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){} chain.doFilter(req,res);} }
